begin
  -- throw-away profiles + products + settings (rolled back at the end)
  insert into public.profiles (user_id, role) values
    (v_admin, 'admin'), (v_page, 'helia'), (v_store, 'mahdi');

  insert into public.products (name, base_price, hp, available, archived)
    values ('ClaimsTest P1', 4000000, 1000000, true, false) returning id into v_p1;
  insert into public.products (name, base_price, hp, available, archived)
    values ('ClaimsTest P2', 5000000, 500000, true, false) returning id into v_p2;
  insert into public.products (name, base_price, hp, available, archived)
    values ('ClaimsTest P3', 1000000, 1000000, true, false) returning id into v_p3;

  insert into public.settings (key, value) values
    ('post_fee', '190000'), ('snapp_multiplier', '1.15'), ('rounding_step', '5000')
  on conflict (key) do update set value = excluded.value;

  -- =============================================== (1) role gate ==========
  -- the store (mahdi) and a signed-in non-member may neither record nor void
  for v_claims in
    select unnest(array[
      '{"sub":"' || v_store || '"}',
      '{"sub":"' || v_out   || '"}'])
  loop
    execute 'set local role authenticated';
    execute 'set local request.jwt.claims = ''' || v_claims || '''';
    begin
      perform public.record_page_claim_receipt(1, current_date, null, null);
      raise exception 'record_page_claim_receipt should have raised for %', v_claims;
    exception when raise_exception then
      if SQLERRM <> 'فقط پیج یا ادمین می‌تواند دریافتی ثبت کند' then raise; end if;
    end;
    begin
      perform public.void_page_claim_receipt(gen_random_uuid(), null);
      raise exception 'void_page_claim_receipt should have raised for %', v_claims;
    exception when raise_exception then
      if SQLERRM <> 'فقط پیج یا ادمین می‌تواند دریافتی را ابطال کند' then raise; end if;
    end;
  end loop;

  -- =============================================== (2) ineligible orders ==
  execute 'reset role';
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_page || '"}''';

  -- pure cash, courier, paid -> claim 0
  v_o_cash := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p2, 'qty', 1)),
    'Cash Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'cash', 0, 'helia', null, null, 'paid', null);
  -- pure cash still new
  v_o_new := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p2, 'qty', 1)),
    'New Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'cash', 0, 'helia', null, null, null, null);
  -- pure snap -> awaiting_snapp
  v_o_await := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p2, 'qty', 1)),
    'Awaiting Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'snapp', 0, 'helia', 1.13, null, null, null);
  -- pure cash to be cancelled after paid
  v_o_cancel := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p2, 'qty', 1)),
    'Cancel Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'cash', 0, 'helia', null, null, 'paid', null);
  perform public.cancel_order(v_o_cancel);

  -- automatic receipt with NO eligible order must reject with the maximum
  begin
    perform public.record_page_claim_receipt(1, current_date, null, null);
    raise exception 'auto receipt should have raised with no eligible order';
  exception when raise_exception then
    if position('حداکثر مجاز 0 تومان' in SQLERRM) = 0 then raise; end if;
  end;

  -- manual allocations against each ineligible order never go through
  begin -- claim 0 (pure cash, paid): nothing collectable
    perform public.record_page_claim_receipt(1, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_cash, 'amount', 1)));
    raise exception 'claim-0 allocation should have raised';
  exception when raise_exception then
    if SQLERRM <> 'این فاکتور ماندهٔ قابل مطالبه ندارد' then raise; end if;
  end;
  begin -- awaiting_snapp: Snap Pay has not settled to the shop yet
    perform public.record_page_claim_receipt(1, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_await, 'amount', 1)));
    raise exception 'awaiting_snapp allocation should have raised';
  exception when raise_exception then
    if position('قابل مطالبه نیست' in SQLERRM) = 0
       or position('awaiting_snapp' in SQLERRM) = 0 then raise; end if;
  end;
  begin -- new
    perform public.record_page_claim_receipt(1, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_new, 'amount', 1)));
    raise exception 'new allocation should have raised';
  exception when raise_exception then
    if position('قابل مطالبه نیست' in SQLERRM) = 0
       or position('new' in SQLERRM) = 0 then raise; end if;
  end;
  begin -- cancelled
    perform public.record_page_claim_receipt(1, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_cancel, 'amount', 1)));
    raise exception 'cancelled allocation should have raised';
  exception when raise_exception then
    if position('قابل مطالبه نیست' in SQLERRM) = 0
       or position('cancelled' in SQLERRM) = 0 then raise; end if;
  end;

  -- =============================================== (3) partial receipts ===
  -- T1 replica: pure Snap courier -> claim = h_share, debt 0
  v_o_p := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p1, 'qty', 1)),
    'Partial Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'snapp', 0, 'helia', 1.13, null, null, null);
  perform public.set_order_status(v_o_p, 'paid');
  select * into r from public.orders where id = v_o_p;
  if r.snapp_deposit <> 5500000 or r.owe <> 5000000 then
    raise exception 'T1 replica money: %/%', r.snapp_deposit, r.owe;
  end if;
  if public.order_page_claim(r) <> 500000 or public.order_page_debt(r) <> 0 then
    raise exception 'T1 replica split: %/%',
      public.order_page_claim(r), public.order_page_debt(r);
  end if;

  -- only eligible order so far: v_o_p (claim 1,000,000)
  v_r1 := public.record_page_claim_receipt(500000, current_date, 'قسط اول', null);
  select coalesce(sum(a.amount), 0) into v_sum
    from public.page_claim_allocations a
    join public.page_claim_receipts rc on rc.id = a.receipt_id
   where a.order_id = v_o_p and rc.voided_at is null;
  if v_sum <> 500000 then raise exception 'partial 1: received %', v_sum; end if;

  v_r2 := public.record_page_claim_receipt(500000, current_date, null, null);
  select coalesce(sum(a.amount), 0) into v_sum
    from public.page_claim_allocations a
    join public.page_claim_receipts rc on rc.id = a.receipt_id
   where a.order_id = v_o_p and rc.voided_at is null;
  if v_sum <> 1000000 then raise exception 'partial 2: received %', v_sum; end if;
  -- both receipts allocated to the SAME invoice
  select count(*) into v_n from public.page_claim_allocations where order_id = v_o_p;
  if v_n <> 2 then raise exception 'partial: allocation rows %', v_n; end if;
  -- a receipt larger than the total remaining is rejected
  begin
    perform public.record_page_claim_receipt(1, current_date, null, null);
    raise exception 'over-total receipt should have raised';
  exception when raise_exception then
    if position('حداکثر مجاز 0 تومان' in SQLERRM) = 0 then raise; end if;
  end;

  -- =============================================== (4) more split cases ===
  -- T5 replica: mixed v5 cash 100,000 + Snap 6,100,000, courier
  v_o_t5 := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p2, 'qty', 1)),
    'Mixed Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'mixed', 0, 'helia', 1.13, null, null, null, null, 100000);
  perform public.set_order_status(v_o_t5, 'paid');
  select * into r from public.orders where id = v_o_t5;
  if r.snapp_deposit <> 5400000 or r.owe <> 5000000 then
    raise exception 'T5 replica money: %/%', r.snapp_deposit, r.owe;
  end if;
  if public.order_page_claim(r) <> 490909 or public.order_page_debt(r) <> 90909 then
    raise exception 'T5 replica split: %/%',
      public.order_page_claim(r), public.order_page_debt(r);
  end if;

  -- T10 replica: a legacy mixed row (fee_in_snapp = false, test M2) — direct
  -- owner insert (legacy rows predate create_order's v5 arguments)
  execute 'reset role';
  insert into public.orders (
    customer, phone, address, postal_code, items, method, shipping_method,
    shipping_payment_method, shipping_fee, snapp_multiplier, rounding_step,
    discount, discount_bearer, total, owe, h_share, payout, status,
    snapp_part, snapp_charge, cash_charge, snapp_fee, snapp_deposit, fee_in_snapp
  ) values (
    'Legacy Customer', '09121234567', 'Tehran', '1234567890', '[]'::jsonb,
    'mixed', 'post', 'cash', 190000, 1.15, 5000,
    0, 'helia', 890000, 690000, 150000, 840000, 'paid',
    325000, 325000, 565000, 50000, 275000, false)
  returning id into v_o_t5;
  select * into r from public.orders where id = v_o_t5;
  if public.order_page_claim(r) <> 63462 or public.order_page_debt(r) <> 478462 then
    raise exception 'T10 replica split: %/%',
      public.order_page_claim(r), public.order_page_debt(r);
  end if;
  delete from public.orders where id = v_o_t5;   -- fixture done (no allocations)
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_page || '"}''';

  -- =============================================== (5) FIFO + split ======= 
  execute 'reset role';
  update public.orders set created_at = now() - interval '5 hours' where id = v_o_p;
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_page || '"}''';

  v_o_a := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p2, 'qty', 1)),
    'FIFO A', '09121234567', 'Tehran', '1234567890',
    'courier', 'snapp', 0, 'helia', 1.13, null, null, null);
  perform public.set_order_status(v_o_a, 'paid');
  v_o_b := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p3, 'qty', 1)),
    'FIFO B', '09121234567', 'Tehran', '1234567890',
    'courier', 'snapp', 0, 'helia', 1.13, null, null, null);
  perform public.set_order_status(v_o_b, 'paid');

  execute 'reset role';
  update public.orders set created_at = now() - interval '4 hours' where id = v_o_a;
  update public.orders set created_at = now() - interval '3 hours' where id = v_o_b;
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_page || '"}''';

  -- v_o_p is fully received; the receipt must split across the two next ones
  -- (v_o_t5 stays newer than v_o_b and is never reached)
  v_r3 := public.record_page_claim_receipt(1200000, current_date, 'FIFO', null);
  select a.order_id, a.amount into r
    from public.page_claim_allocations a where a.receipt_id = v_r3
   order by a.order_created_at asc;
  if r.order_id <> v_o_a or r.amount <> 500000 then
    raise exception 'FIFO first: %/%', r.order_id, r.amount;
  end if;
  select a.order_id, a.amount into r
    from public.page_claim_allocations a where a.receipt_id = v_r3
   order by a.order_created_at desc;
  if r.order_id <> v_o_b or r.amount <> 700000 then
    raise exception 'FIFO second: %/%', r.order_id, r.amount;
  end if;

  -- =============================================== (6) manual mode ========
  v_o_m := public.create_order(
    jsonb_build_array(jsonb_build_object('product_id', v_p3, 'qty', 1)),
    'Manual Customer', '09121234567', 'Tehran', '1234567890',
    'courier', 'snapp', 0, 'helia', 1.13, null, null, null);
  perform public.set_order_status(v_o_m, 'paid');
  execute 'reset role';
  update public.orders set created_at = now() - interval '2 hours' where id = v_o_m;
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_page || '"}''';

  -- sum != amount
  begin
    perform public.record_page_claim_receipt(600000, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_m, 'amount', 500000)));
    raise exception 'sum mismatch should have raised';
  exception when raise_exception then
    if position('باید دقیقاً برابر مبلغ دریافتی' in SQLERRM) = 0 then raise; end if;
  end;
  -- over-allocation
  begin
    perform public.record_page_claim_receipt(1500000, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_m, 'amount', 1500000)));
    raise exception 'over-allocation should have raised';
  exception when raise_exception then
    if position('از ماندهٔ این فاکتور' in SQLERRM) = 0 then raise; end if;
  end;
  -- duplicate invoice
  begin
    perform public.record_page_claim_receipt(600000, current_date, null,
      jsonb_build_array(
        jsonb_build_object('order_id', v_o_m, 'amount', 300000),
        jsonb_build_object('order_id', v_o_m, 'amount', 300000)));
    raise exception 'duplicate allocation should have raised';
  exception when raise_exception then
    if SQLERRM <> 'هر فاکتور فقط یک بار در تخصیص‌ها می‌تواند بیاید' then raise; end if;
  end;
  -- empty allocation array
  begin
    perform public.record_page_claim_receipt(1, current_date, null, '[]'::jsonb);
    raise exception 'empty allocation should have raised';
  exception when raise_exception then
    if position('آرایه‌ای غیرخالی' in SQLERRM) = 0 then raise; end if;
  end;
  -- amount must be positive
  begin
    perform public.record_page_claim_receipt(0, current_date, null, null);
    raise exception 'zero amount should have raised';
  exception when raise_exception then
    if SQLERRM <> 'مبلغ دریافتی باید عددی مثبت باشد' then raise; end if;
  end;
  -- a fully-received invoice cannot be allocated again
  begin
    perform public.record_page_claim_receipt(1000, current_date, null,
      jsonb_build_array(jsonb_build_object('order_id', v_o_p, 'amount', 1000)));
    raise exception 'fully-received allocation should have raised';
  exception when raise_exception then
    if SQLERRM <> 'این فاکتور ماندهٔ قابل مطالبه ندارد' then raise; end if;
  end;
  -- a valid manual receipt
  v_r4 := public.record_page_claim_receipt(600000, current_date, 'دستی', null,
    jsonb_build_array(jsonb_build_object('order_id', v_o_m, 'amount', 600000)));
  select coalesce(sum(a.amount), 0) into v_sum
    from public.page_claim_allocations a
    join public.page_claim_receipts rc on rc.id = a.receipt_id
   where a.order_id = v_o_m and rc.voided_at is null;
  if v_sum <> 600000 then raise exception 'manual received %', v_sum; end if;

  -- =============================================== (7) future received_on =
  begin
    perform public.record_page_claim_receipt(1, current_date + 1, null, null);
    raise exception 'future received_on should have raised';
  exception when raise_exception then
    if SQLERRM <> 'تاریخ دریافت نمی‌تواند در آینده باشد' then raise; end if;
  end;

  -- =============================================== (8) void ===============
  perform public.void_page_claim_receipt(v_r1, 'اشتباه ثبت بود');
  select coalesce(sum(a.amount), 0) into v_sum
    from public.page_claim_allocations a
    join public.page_claim_receipts rc on rc.id = a.receipt_id
   where a.order_id = v_o_p and rc.voided_at is null;
  if v_sum <> 500000 then raise exception 'void restore: received %', v_sum; end if;
  -- idempotent: voiding twice is a no-op, and the row stays in history
  perform public.void_page_claim_receipt(v_r1, null);
  select count(*) into v_n from public.page_claim_receipts
   where id = v_r1 and voided_at is not null;
  if v_n <> 1 then raise exception 'void idempotent'; end if;
  -- the re-receipt goes to the oldest invoice with a remaining (v_o_p)
  v_r2 := public.record_page_claim_receipt(500000, current_date, null, null);
  select a.order_id, a.amount into r
    from public.page_claim_allocations a where a.receipt_id = v_r2;
  if r.order_id <> v_o_p or r.amount <> 500000 then
    raise exception 're-receipt: %/%', r.order_id, r.amount;
  end if;

  -- =============================================== (9) admin delete/restore
  execute 'reset role';
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_admin || '"}''';
  begin
    perform public.admin_delete_order(v_o_p);
    raise exception 'allocated delete should have raised';
  exception when raise_exception then
    if SQLERRM <> 'این سفارش تخصیصِ دریافتی دارد؛ ابتدا دریافتی مربوط را ابطال یا جابه‌جا کنید'
      then raise; end if;
  end;
  -- an order without allocations can still be deleted and restored
  perform public.admin_delete_order(v_o_cash);
  select a.id into r from public.audit_log a
   where a.entity = 'order' and a.action = 'delete' and a.entity_id = v_o_cash
   order by a.at desc limit 1;
  v_claim := public.admin_restore_order(r.id);
  if v_claim <> v_o_cash then raise exception 'restore id %', v_claim; end if;

  -- =============================================== (10) mismatch ==========
  -- v_o_m: received 600,000; lower the claim to 500,000 via an admin edit
  -- (swap the item to the hp-500,000 product)
  perform public.admin_update_order(v_o_m,
    jsonb_build_object('items', jsonb_build_array(
      jsonb_build_object('product_id', v_p2, 'qty', 1))));
  select * into r from public.orders where id = v_o_m;
  v_claim := public.order_page_claim(r);
  select coalesce(sum(a.amount), 0) into v_sum
    from public.page_claim_allocations a
    join public.page_claim_receipts rc on rc.id = a.receipt_id
   where a.order_id = v_o_m and rc.voided_at is null;
  if not (v_sum > v_claim) then
    raise exception 'mismatch not reached: received % claim %', v_sum, v_claim;
  end if;
  if v_sum - v_claim <> 100000 then raise exception 'mismatch delta %', v_sum - v_claim; end if;

  -- =============================================== (11) no outbox events ==
  execute 'reset role';
  select count(*) into v_outbox0 from public.outbox;
  select count(*) into v_events0 from public.tg_order_events();

  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_admin || '"}''';
  v_n := public.record_page_claim_receipt(300000, current_date, 'ادمین', null,
    jsonb_build_array(jsonb_build_object('order_id', v_o_b, 'amount', 300000)));
  perform public.void_page_claim_receipt(v_n, null);
  execute 'reset role';
  select count(*) into v_outbox1 from public.outbox;
  if v_outbox1 <> v_outbox0 then
    raise exception 'outbox rows created: % -> %', v_outbox0, v_outbox1;
  end if;
  select count(*) into v_events1 from public.tg_order_events();
  if v_events1 <> v_events0 then
    raise exception 'tg_order_events changed: % -> %', v_events0, v_events1;
  end if;

  -- =============================================== (12) RLS + sweep =======
  -- members read the ledger; a signed-in non-member reads nothing
  execute 'set local role authenticated';
  execute 'set local request.jwt.claims = ''{"sub":"' || v_page || '"}''';
  select count(*) into v_n from public.page_claim_receipts;
  if v_n < 3 then raise exception 'member reads % receipts', v_n; end if;
  execute 'set local request.jwt.claims = ''{"sub":"' || v_out || '"}''';
  select count(*) into v_n from public.page_claim_receipts;
  if v_n <> 0 then raise exception 'non-member reads % receipts', v_n; end if;
  execute 'reset role';

  -- the 500-combo sweep: the SQL functions must return EXACTLY the JS values
  -- (the tuples are generated by the same seeded sweep as tests.html)
  for i in 0 .. jsonb_array_length(v_tuples) - 1 loop
    t := v_tuples -> i;
    o_row := jsonb_populate_record(null::public.orders, jsonb_build_object(
      'total',    (t->>0)::bigint,
      'owe',      (t->>1)::bigint,
      'h_share',  (t->>2)::bigint,
      'payout',   (t->>3)::bigint,
      'snapp_part',   (t->>4)::bigint,
      'snapp_charge', (t->>5)::bigint,
      'cash_charge',  (t->>6)::bigint,
      'snapp_fee',    (t->>7)::bigint,
      'snapp_deposit',(t->>8)::bigint,
      'shipping_fee', (t->>9)::bigint,
      'method',   (array['cash','snapp','mixed'])[(t->>10)::int + 1],
      'fee_in_snapp', (t->>11)::int = 1,
      'shipping_payment_method', (array['cash','snapp'])[(t->>12)::int + 1]));
    v_claim := public.order_page_claim(o_row);
    v_debt  := public.order_page_debt(o_row);
    if v_claim < 0 or v_debt < 0 then
      raise exception 'sweep %: negative claim/debt %/%', i, v_claim, v_debt;
    end if;
    if (o_row.snapp_deposit - v_claim) + v_debt <> o_row.owe then
      raise exception 'sweep %: conservation % + % <> %', i, v_claim, v_debt, o_row.owe;
    end if;
    if o_row.h_share > 0 and v_claim > o_row.h_share then
      raise exception 'sweep %: claim % > h_share %', i, v_claim, o_row.h_share;
    end if;
    if v_claim <> (t->>13)::bigint or v_debt <> (t->>14)::bigint then
      raise exception 'sweep %: js %/% but sql %/%', i, t->>13, t->>14, v_claim, v_debt;
    end if;
    -- drift guard: the inline section-1 formula must equal the function
    v_net := (o_row.owe - o_row.shipping_fee + o_row.h_share)::numeric;
    v_gs  := (o_row.snapp_deposit - (case when o_row.shipping_payment_method = 'snapp'
                                          then o_row.shipping_fee else 0 end))::numeric;
    v_inline := (case when v_net <= 0 or o_row.h_share <= 0 or v_gs <= 0
                      then 0::numeric
                      else least(v_gs, round(o_row.h_share::numeric * v_gs / v_net)) end)::bigint;
    if v_inline <> v_claim then
      raise exception 'sweep %: drift function % inline %', i, v_claim, v_inline;
    end if;
  end loop;

  raise notice 'ALL PASSED (page_claims.sql): role gate, ineligible orders, partial receipts, FIFO split, manual validation, future date, void, delete/restore, mismatch, outbox, RLS, 500-combo JS parity';
end;
$$;

rollback;
